code_example.solutionCode:
import random
secret = random.randint(1, 10)
for turn in range(3):
    guess = int(input("Guess a number from 1 to 10: "))
    if guess == secret:
        print("You win!")
        break
    elif guess < secret:
        print("Too low!")
    else:
        print("Too high!")
print("The number was", secret)
